"""One-shot independent reviewer acceptance. Never authors the candidate policy."""
from pathlib import Path
import datetime,hashlib,importlib.util,json
R=Path(__file__).resolve().parents[2];D=Path(__file__).resolve().parent
sha=lambda b:hashlib.sha256(b).hexdigest();read=lambda p:json.loads(p.read_text());canon=lambda x:json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False)
p=read(R/'data/learning-resource-policy.json');m=read(R/'audits/final-ui-policy-104-author/candidate-manifest.json');ledgerpath=R/'data/learning-resource-policy-reviews.json';ledger=read(ledgerpath)
assert sha(ledgerpath.read_bytes())=='f88448a5f1e260ad93b1144003dccf95b64ec2d7df2dc4fe753857ed1f1cf645'
assert p['version']=='1.0.4' and sha(canon(p).encode())==m['policySha256']=='3405deb0579e240237a25cba823ddb52156b03e48621a55d8992410019c83bb9'
assert sha((R/'data/learning-resource-policy.json').read_bytes())==m['policyFileSha256']=='df5503040f4fc6fb44c75e112e101afb6ade6f7373745f0b23058acb8fe99725'
assert p['codeHashes']==m['codeHashes'] and all(sha((R/f).read_bytes())==h for f,h in p['codeHashes'].items())
counts={}
for name in ['binding-checks','followup-probes','real-followup-probes','visual-producer-probes','visual-runtime-probes','visual-ui-probes','actual-visual-runtime','independent-ui-checks']:
 x=read(D/(name+'.json'));assert x['failed']==0;counts[name]=x['passed']
assert 'ℹ pass 128' in (D/'shared-node-explicit-allowlist.log').read_text();assert 'Ran 188 tests' in (D/'shared-python.log').read_text() and (D/'shared-python.log').read_text().rstrip().endswith('OK')
files=sorted(f for f in D.iterdir() if f.is_file() and f.suffix in ('.json','.js','.py','.log','.patch') and f.name not in ['independent-review-summary.json'])
evidence={str(f.relative_to(R)):sha(f.read_bytes()) for f in files}
record={'id':'recovery-independent-learning-resource-policy-v1.0.4','reviewerId':'verify_remaining_assignment_answers:independent-ui-policy-reviewer','reviewedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'resourceId':p['id'],'resourceVersion':p['version'],'resourceSha256':m['policySha256'],'decision':'verified','checks':{k:True for k in p['requiredChecks']},'findings':[],'codeHashes':p['codeHashes'],'priorExposure':'Disclosed nonblind independent code review. Prior accepted implementation, author neutral diffs, handoffs and author test fixtures were inspected. Reviewer-owned Python/JavaScript fixtures and actual question objects were used independently. Pending-policy approvals existed only in explicit in-memory software tests before this acceptance. This reviewer did not author question answers, visual classification or crop fidelity approvals.','closedFindings':{'UI104-R01':'Focus recommendation limit:null now stays unbounded until ordinary filters are applied, then eight visible suggestions are selected.','UI104-R02':'Visual runtime now requires attachment of a current accepted answer review ID to the question, matching producer eligibility.','UI104-R03':'An already-open full-source preview is revoked on active exam entry; save/zoom independently enforce current saved crop identity and stale practice callbacks cannot bypass it.','UI104-R04':'Previously prepared answer-key print content is cleared on exam entry; native beforeprint independently rechecks exam state, current input approval and decoding, preventing stale keyed print content.'},'evidencePaths':list(evidence),'evidenceSha256':evidence,'limitations':['This acceptance is for exact policy-bound code and deterministic behavior, not browser layout/interaction QA.','Separate independent input classification and crop review is still ongoing. The bounded actual snapshot has1397 ready and3672 blocked of5069 verified questions; missing inputs fail closed. This is not whole-course visual completeness.','Reviewer accidentally invoked two legacy browser runners via an overly broad Node glob. Both launches failed before any page check or screenshot; no retry occurred. Exact incident and both overwritten reports are preserved in this review directory; ordinary process inspection found no remaining browser processes. Later software suite used an explicit file allowlist.','Offline HTML and JSON backups contain readable answer data by design. UI exam isolation is not encrypted or proctored secrecy.']}
assert not {record['reviewerId']}.intersection({p['authorId'],*p.get('revisionAuthors',[])})
assert not any(r['id']==record['id'] for r in ledger)
ledgerpath.write_text(json.dumps(ledger+[record],ensure_ascii=False,indent=2)+'\n')
summary={'recordedAt':record['reviewedAt'],'decision':'verified exact code; visual inventory completion and browser QA remain separate','reviewId':record['id'],'policySha256':m['policySha256'],'policyFileSha256':m['policyFileSha256'],'policyReviewLedgerSha256':sha(ledgerpath.read_bytes()),'codeHashes':p['codeHashes'],'independentProbeCounts':counts,'actualSubtopicScopes':read(D/'actual-bank-navigation-check.json')['lazySubtopicLinks'],'sharedNodeTestsPassed':128,'sharedPythonTestsPassed':188,'closedFindings':record['closedFindings'],'genuineVisualSnapshot':read(D/'actual-visual-producer.json'),'browserVerified':False,'executionIncident':'audits/final-ui-policy-104-review/execution-incident.json','limitations':record['limitations'],'evidenceSha256':evidence}
(D/'independent-review-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:summary[k] for k in ['decision','reviewId','policySha256','policyReviewLedgerSha256','independentProbeCounts','sharedNodeTestsPassed','sharedPythonTestsPassed']},indent=2));print('summarySha256',sha((D/'independent-review-summary.json').read_bytes()))
